    for key, value in attrs.items():
        if value is not None:
            attr_str += ' {}="{}"'.format(key, escape_text(value))
    return '<img{} />\n'.format(attr_str)


def render_figure(self: Any, text: str, align: Optional[str]=None, figwidth:
    Optional[str]=None, figclass: Optional[str]=None) ->str:
    fig_attr = ''
    if align:
        fig_attr += ' align="{}"'.format(align)
    if figwidth:
        fig_attr += ' figwidth="{}"'.format(figwidth)
    if figclass:
